Lemma pv_out_cases : forall bs, let r := pv_out bs in
  (exists e loc, pv_err r = Some (e, loc) /\ (e = HE_BAD_VERSION \/ e = HE_NEED_MORE)
      /\ Z.even loc = true /\ 4 <= loc /\ loc + 1 < 2^64 /\ 0 <= pv_result_cell r 0 < 2^32 /\ 0 <= pv_adv r <= 8)
  \/ (pv_err r = None /\ pv_adv r = 8 /\ (8 <= length bs)%nat /\ exists v, pv_result r = Some v /\ 0 <= v <= 99).
Proof.
  intros bs. cbn beta.
  destruct bs as [|c0 [|c1 [|c2 [|c3 [|c4 [|c5 [|c6 [|c7 rest]]]]]]]];
    try (left; exists HE_NEED_MORE, LOC_PV_NM; cbn; unfold LOC_PV_NM; repeat split; try reflexivity; try lia; right; reflexivity).
  unfold pv_out.
  pose proof (zb_range c5) as R5. pose proof (zb_range c7) as R7.
  destruct (zb c0 =? 72); cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_H; repeat split; try lia; try reflexivity; left; reflexivity].
  destruct (zb c1 =? 84); cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_T1; repeat split; try lia; try reflexivity; left; reflexivity].
  destruct (zb c2 =? 84); cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_T2; repeat split; try lia; try reflexivity; left; reflexivity].
  destruct (zb c3 =? 80); cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_P; repeat split; try lia; try reflexivity; left; reflexivity].
  destruct (zb c4 =? 47); cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_SLASH; repeat split; try lia; try reflexivity; left; reflexivity].
  destruct (is_digitc (zb c5)) eqn:D5; cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_D1; repeat split; try lia; try reflexivity; left; reflexivity].
  apply is_digitc_iff in D5.
  destruct (zb c6 =? 46); cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_DOT; repeat split; try lia; try reflexivity; left; reflexivity].
  destruct (is_digitc (zb c7)) eqn:D7; cbn [negb]; [| left; do 2 eexists; split; [reflexivity|]; cbn; unfold LOC_PV_D2; repeat split; try lia; try reflexivity; left; reflexivity].
  apply is_digitc_iff in D7.
  right. cbn. repeat split; try reflexivity; try lia. eexists. split; [reflexivity|]. lia.
Qed.

Lemma land64_mod' : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. reflexivity. Qed.
Lemma swrap32_small : forall z, -2^31 <= z < 2^31 -> bv_swrap 32 z = z.
Proof. intros z H. apply bv_swrap_small. replace (bv_half_modulus 32) with (2^31) by (vm_compute; reflexivity). lia. Qed.

