Lemma Z_to_bv_eqm64 : forall a b, a mod 2^64 = b mod 2^64 -> Z_to_bv 64 a = Z_to_bv 64 b.
Proof. intros a b E. rewrite <- (Z_to_bv_mod64 a), <- (Z_to_bv_mod64 b), E. reflexivity. Qed.
Lemma unsigned_negj : forall j, 0 <= j < 2^64 -> bv_unsigned (Z_to_bv 64 (- j)) = (- j) mod 2^64.
Proof. intros j Hj. rewrite Z_to_bv_unsigned. reflexivity. Qed.
Lemma neg_negj : forall j, 0 <= j < 2^64 -> Z_to_bv 64 (0 + - bv_unsigned (Z_to_bv 64 (- j))) = Z_to_bv 64 j.
Proof.
  intros j Hj. rewrite unsigned_negj by lia. apply Z_to_bv_eqm64. Z.div_mod_to_equations. lia.
Qed.
