Lemma snez_xor_pos : forall a b, 0 < a -> 0 < b -> Z.lxor (Z.b2z (0 <? a)) (Z.b2z (0 <? b)) = 0.
Proof.
  intros a b Ha Hb. replace (0 <? a) with true by (symmetry; apply Z.ltb_lt; lia).
  replace (0 <? b) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity.
