Definition isl_p3_stmt : Prop :=
  forall (r : pv_res) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 k j : Z) (bs mbs tbs : list byte)
    (j4 jt : list byte) (g : bool),
  isl_ctx m m1 sp (isl_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs (pv_ec r EC_clear) (pv_cat r g) ->
  rw_cells usegs m1 (bv_unsigned sp + -112) [CB 4 j4; C4 (wz (pv_result_cell r 0)); C8 (wz (p0 + k + j + 2 + pv_adv r)); CB 24 jt] ->
  isl_pure sp P IN E lo c p0 bs ->
  bytes_at usegs m1 p0 mbs -> bytes_at usegs m1 (p0 + k + 1) tbs -> Z.of_nat (length mbs) = k -> Z.of_nat (length tbs) = j ->
  1 <= k -> 1 <= j -> p0 + k + j + 2 <= p0 + Z.of_nat (length bs) ->
  r = pv_out (skipn (Z.to_nat (k + j + 2)) bs) ->
  evt usegs (isl_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz k) (wz (p0 + k + 1)) (wz j) s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3e68c) fc None m1 (seg_rom usegs)).

