Local Ltac isl_p3_tail f1 v p0 mbs tbs lo sp P E :=
  let SV := fresh "SV" in
  (* [comment removed for export] *)
  step; step; step;
  pose proof S2V as SV; unfold string_to_verb_stmt, string_to_verb_post, verb_post_v, STRING_TO_VERB_STACK, P_STRING_TO_VERB in SV; unfold wz in SV;
  lazymatch goal with WM_ : bytes_at _ ?mx p0 mbs, ST' : stk _ ?mx lo _, MI' : mem_inv _ ?mx |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    callZ (SV p0 mbs lo _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ mx);
    [ exact WM_ | lia | rewrite unsigned_lit by lia; exact ST' | rewrite unsigned_lit by lia; lia | lia
    | rewrite unsigned_lit by lia; lia | lia (* [comment removed for export] *) | exact MI' | clear SV ]
  end;
  (* [comment removed for export] *)
  lazymatch goal with HC : HttpCat _ _, XS : XStatics _, MUq : munch [(lo, bv_unsigned sp); (P, P + 80)]%Z _ ?mx, WMq : wmono _ _ ?mx
    |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    let HC' := fresh "HC'" in let XS' := fresh "XS'" in let VT := fresh "VT" in
    pose proof (HttpCat_transport _ _ _ _ HC MUq WMq ltac:(unfold G_HTTP_CAT; cbn; lia) ltac:(unfold G_HTTP_CAT_GUARD; cbn; lia)) as HC';
    pose proof (XStatics_transport _ _ _ XS MUq WMq ltac:(repeat constructor; cbn; lia)) as XS';
    clear HC XS MUq WMq;
    pose proof (XStatics_parser_vt _ XS') as VT; unfold parser_vt_cells in VT;
    step; step; change (sx32 (Z_to_bv 64 v)) with (sx32 (wz v)); rewrite sx32_wz by lia; unfold wz;
    unfold VP_PARSER; step; clear VT;
    step; step; step; step; step; step; step; step
  end;
  apply evt_done; right; unfold isl_call_post, ISL_RET, P_ON_REQUEST_IMPL, isl_sv, isl_W, G_HTTP_CAT, ParserCoreCells; unfold wz;
  cbn [map pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f];
  do 8 eexists; exists (Z.of_nat (length mbs)), (Z.of_nat (length tbs)), v, f1; exists mbs, tbs; do 2 eexists;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try eassumption; try reflexivity; try lia.
