Lemma pv_call : forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (q I R E lo last : Z) (bs : list byte) (r0 : Z) (E0 : ecv) (g : bool),
  bytes_at usegs m q bs -> last = q + Z.of_nat (length bs) ->
  rw_cells usegs m I [C8 (wz q)] -> rw_cells usegs m R [C4 (wz r0)] -> rw_cells usegs m E (ErrCodeCells E0) ->
  HttpCat m g -> XStatics m -> stk usegs m lo (bv_unsigned sp) -> pv_pure sp q I R E lo bs r0 E0 -> mem_inv usegs m ->
  evt usegs (pv_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo bs r0 E0 g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz I) (wz last) (wz R) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_VERSION) fc None m (seg_rom usegs)).
Proof. intros. subst last. eapply pv_spec; eassumption. Qed.

