Definition isl_tfound_stmt : Prop :=
  forall (cc : Z) rax ra sp gp tp t0 t1 t2 a3 a4 a5 a6 s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 k j aj qj q1 : Z) (bs : list byte)
    (j8 jt : list byte) (ppv : word) (g : bool),
  isl_ctx m m1 sp (isl_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs EC_clear g ->
  rw_cells usegs m1 (bv_unsigned sp + -112) [CB 8 j8] ->
  rw_cells usegs m1 (bv_unsigned sp + -104) [C8 ppv] ->
  rw_cells usegs m1 (bv_unsigned sp + -96) [CB 24 jt] ->
  isl_pure sp P IN E lo c p0 bs ->
  1 <= k -> 0 <= j -> p0 + k + 1 + j < p0 + Z.of_nat (length bs) -> 0 <= cc < 256 ->
  aj = - j -> qj = p0 + k + 1 + j -> q1 = p0 + k + 1 ->
  evt usegs (isl_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz P) (wz 0) (wz aj) (wz qj) a3 a4 a5 a6 (wz cc)
              (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz k) (wz q1) s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3e574) fc None m1 (seg_rom usegs)).

