Lemma isl_tloop_all : forall n, TLOOP_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros j. intros until g. intros CTX LOW8 PP TMP PURE K1 J0 QB NM AJ QJ Q1. exfalso. cbn [Z.of_nat] in NM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply isl_tloop_step. exact IH.
Qed.


(* [comment removed for export] *)
Definition isl_mfound_stmt : Prop :=
  forall (cm : Z) rax ra sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 k k1 pk : Z) (bs : list byte)
    (j8 jt : list byte) (ppv : word) (g : bool),
  isl_ctx m m1 sp (isl_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs EC_clear g ->
  rw_cells usegs m1 (bv_unsigned sp + -112) [CB 8 j8] ->
  rw_cells usegs m1 (bv_unsigned sp + -104) [C8 ppv] ->
  rw_cells usegs m1 (bv_unsigned sp + -96) [CB 24 jt] ->
  isl_pure sp P IN E lo c p0 bs ->
  0 <= k -> p0 + k < p0 + Z.of_nat (length bs) -> 0 <= cm < 256 -> k1 = k + 1 -> pk = p0 + k ->
