Lemma isl_mloop_all : forall n, MLOOP_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros i. intros until g. intros CTX LOW8 PP SL TMP PURE I0 QB NM. exfalso. cbn [Z.of_nat] in NM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply isl_mloop_step. exact IH.
Qed.

(* [comment removed for export] *)
Definition isl_segA_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (g : bool),
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells usegs m IN [C8 (wz p0)] ->
  rw_cells usegs m E (ErrCodeCells EC_clear) ->
  bytes_at usegs m p0 bs -> HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) ->
  isl_pure sp P IN E lo c p0 bs -> mem_inv usegs m ->
  evt usegs (isl_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_INNER_PARSE_START_LINE) fc None m (seg_rom usegs)).

